/// <summary>
/// The NVOrderApprovalEventHandler workflow outcome event handler.
/// </summary>
public final class NVOrderApprovalEventHandler implements WorkflowElementCanceledEventHandler,
	WorkflowElemChangeRequestedEventHandler,
	WorkflowElementCompletedEventHandler,
	WorkflowElementReturnedEventHandler,
	WorkflowElementStartedEventHandler,
	WorkflowElementDeniedEventHandler,
	WorkflowWorkItemsCreatedEventHandler
{
}

Method.Source:
    /// <summary>
    /// Fired when an individual approval step starts.
    /// No status change needed — header is already PendingApproval.
    /// </summary>
    public void started(WorkflowElementEventArgs _workflowElementEventArgs)
	{
        // TODO:  Write code to execute once the workflow is denied.
	}

    /// <summary>
    /// Fired when an approval step is cancelled (e.g., workflow recalled mid-step).
    /// </summary>
    public void canceled(WorkflowElementEventArgs _workflowElementEventArgs)
	{
        // TODO:  Write code to execute once the workflow is denied.
	}

///// <summary>
///// Fired when approver clicks Approve on their step.
///// Captures the approver as final approver on NVOrderHeader.
///// Last completed step overwrites — final stage approver becomes official signer.
///// Uses root correlation ID to ensure correct workflow instance lookup.
///// </summary>
public void completed(WorkflowElementEventArgs _workflowElementEventArgs)
{
    // Do not persist final approver here.
    // Workflow-level completed() is the reliable one-shot end-of-process hook.
}

    public void denied(WorkflowElementEventArgs _workflowElementEventArgs)
	{
        try
        {
            NVOrderHeader::updateWorkflowStatus(
                _workflowElementEventArgs.parmWorkflowContext().parmRecId(),
                NVOrderStatus::Rejected);
        }
        catch (Exception::Error)
        {
            error("NVOrderApproval: Failed to set status Rejected after denial.");
            throw;
        }
	}

